def comps(grid,diag=True):
  R,C=len(grid),len(grid[0]); seen=set(); res=[]
  ds=[(dr,dc) for dr in (-1,0,1) for dc in (-1,0,1) if (dr or dc) and (diag or abs(dr)+abs(dc)==1)]
  for r in range(R):
   for c in range(C):
    if grid[r][c]!=0 or (r,c) in seen: continue
    st=[(r,c)]; seen.add((r,c)); x=[]
    while st:
     a,b=st.pop();x.append((a,b))
     for dr,dc in ds:
      q=(a+dr,b+dc)
      if 0<=q[0]<R and 0<=q[1]<C and grid[q[0]][q[1]]==0 and q not in seen: seen.add(q);st.append(q)
    res.append(x)
  return sorted(res,key=lambda x:(-len(x),min(x)))
